package com.agacostays.payroll.validation; import com.agacostays.payroll.entity.Payroll; import com.agacostays.payroll.enums.PayrollStatus; import com.agacostays.payroll.exception.BusinessRuleException; import org.springframework.stereotype.Component; @Component public class PayrollValidationService{public void beforeUpdate(Payroll p){if(p.getPaymentStatus()==PayrollStatus.PAID)throw new BusinessRuleException("Paid payroll cannot be edited");}public void beforeCredit(Payroll p){if(p.getPaymentStatus()==PayrollStatus.PAID)throw new BusinessRuleException("Salary already credited");}}